/* Word quotation format options; no signing workflow. */
(function(root){'use strict';
function mount(anchor,{onChange}={}){if(!anchor||!root.QuoteLayouts)return null;const D=anchor.ownerDocument,create=(tag,text,cls)=>{const e=D.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;},controls=new Map(),options={},box=create('fieldset',undefined,'qs-formats');box.id='quote-format-options';box.append(create('legend','报价单格式（可多选）'));for(const f of root.QuoteLayouts.catalog){const input=create('input');input.type='checkbox';input.id='quote-layout-'+f.id;input.value=f.id;controls.set(f.id,input);const label=create('label',undefined,'qs-check');label.append(input,create('span',f.title));box.append(label);input.addEventListener('change',()=>onChange?.());}
const detail=create('details',undefined,'qs-details'),fields=create('div',undefined,'qs-fields');detail.append(create('summary','版式补充信息（选填）'));
for(const [key,label,max] of [['workDays','服务期限／现场天数',60],['validity','报价有效期',100],['costScope','食宿、交通等费用范围',200],['serviceScope','服务范围',200],['authorizedPerson','授权代表姓名',80],['authorizedRole','授权代表职务',80],['firmAddress','供应商地址（格式3）',160],['fax','传真（格式3）',60],['bankName','开户行（格式3，选填）',120],['bankAccount','银行账号（格式3，选填）',80],['legalRepresentative','法定代表人（格式3，选填）',80]]){const input=create('input');input.type='text';input.id='quote-layout-'+key;input.maxLength=max;options[key]=input;const row=create('label',label);row.append(input);fields.append(row);input.addEventListener('input',()=>onChange?.());}
detail.append(fields);anchor.replaceChildren(box,detail,create('p','未勾选时使用格式1；多选格式合成一个 Word，营业执照和执业证书自动附入。','tiny'));
function selection(){return {formats:[...controls].filter(([,e])=>e.checked).map(([id])=>id),options:Object.fromEntries(Object.entries(options).map(([key,e])=>[key,e.value.trim()]))};}
return Object.freeze({selection,restore(data){if(!data||!Array.isArray(data.formats))return;for(const [id,e]of controls)e.checked=data.formats.includes(id);for(const [key,e]of Object.entries(options))if(typeof data.options?.[key]==='string')e.value=data.options[key].slice(0,e.maxLength);},reviewButton:null});}
root.QuoteWordUI=Object.freeze({mount});
})(globalThis);
